select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='run'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='run'),1,false,(select jsonb_agg(jsonb_build_object('external_id',i::text,'payload',jsonb_build_object('id',i,'prescription_id',101))) from generate_series(1,11) i))$$,'23514',null,'Page above application cap rejected');
