select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='run'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='run'),1,false,'[{"external_id":"501","payload":{"id":501,"prescription_id":101,"product_id":true}}]')$$,'23514',null,'Noncanonical or unsafe reference rejected');
