select ok(not has_function_privilege('service_role','stage_ezyvet_import_page_pre_prescriptionitem(uuid,uuid,uuid,integer,boolean,jsonb)','execute'),'Private helper inaccessible to service role');
select ok(not has_function_privilege('service_role','ezyvet_validate_prescriptionitem_prescription(uuid,text,text,uuid,text,integer)','execute'),'Private helper inaccessible to service role');
select ok(not has_function_privilege('service_role','ezyvet_prescriptionitem_run_projection(uuid)','execute'),'Private helper inaccessible to service role');
select throws_ok($$delete from ezyvet_prescriptionitem_pages$$,'23514',null,'Receipts append only');
select throws_ok($$update ezyvet_prescriptionitem_runs set prescription_observed_head_version=999$$,'23514',null,'Pinned context immutable');
-- Native side effects are unchanged by both accepted and rejected observations.
select is(jsonb_build_object('treatments',(select count(*) from patient_treatments),'invoices',(select count(*) from billing_invoices),'stock',(select count(*) from inventory_movements),'certificates',(select count(*) from vaccine_certificates),'reminders',(select count(*) from care_reminder_jobs),'outbox',(select count(*) from communication_outbox)),(select v from data where k='side-effects'),'No treatment, billing, inventory, certificate, reminder or outbox side effects');
-- Return source revisions to a freshly observed current prescription through the real scoped entrypoint.
select set_config('request.jwt.claims','{"sub":"db560000-0000-4000-8000-000000000001","role":"authenticated"}',true);
update ezyvet_import_runs set retry_after=null,lease_until=null;
insert into data select 'fresh-prescription',claim_ezyvet_prescription_import(gen_random_uuid(),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','prescription','https://api.trial.ezyvet.com',(select id from fx where k='mapping'));
select stage_ezyvet_import_page((select (v->>'id')::uuid from data where k='fresh-prescription'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='fresh-prescription'),1,true,'[{"external_id":"101","payload":{"id":101,"animal_id":77,"instructions":"Source prescriptionation"}}]');
update data set v=(select c from jsonb_array_elements(list_ezyvet_prescription_candidates((select id from fx where k='mapping'),'prescription')->'candidates') c where c->>'external_id'='101') where k='prescription';
insert into data select 'string-run',claim_ezyvet_prescriptionitem_import(gen_random_uuid(),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','prescriptionitem','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),(select (v->>'id')::uuid from data where k='prescription'),(select v->>'payload_hash' from data where k='prescription'),(select (v->>'observed_head_version')::integer from data where k='prescription'));
set local role service_role;
select lives_ok($$select stage_ezyvet_import_page((select (v->>'id')::uuid from data where k='string-run'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='string-run'),1,true,'[{"external_id":"601","payload":{"id":"601","prescription_id":"101","product_id":"9007199254740991"}},{"external_id":"602","payload":{"id":602,"prescription_id":101}}]')$$,'Canonical number and string references preserve original representation');
select throws_ok($$select stage_ezyvet_import_page((select (v->>'id')::uuid from data where k='string-run'),'db560000-0000-4000-8000-000000000001',null,1,true,'[{"external_id":"602","payload":{"id":602,"prescription_id":101}},{"external_id":"601","payload":{"id":"601","prescription_id":"101","product_id":"9007199254740991"}}]')$$,'40001',null,'Replay order is immutable despite sorted processing');
set local role authenticated;
select is(list_ezyvet_prescriptionitem_candidates((select id from fx where k='mapping'),null,null,1)->>'has_more','true','Candidate keyset pagination is bounded');
select ok((list_ezyvet_prescriptionitem_candidates((select id from fx where k='mapping'))#>>'{candidates,0,payload,id}') is not null,'Raw source references retained');
reset role;
-- A generic prescription snapshot cannot substitute for validated clinical observation evidence.
update ezyvet_import_runs set retry_after=null,lease_until=null;
insert into data select 'generic-prescription',to_jsonb(claim_ezyvet_import_core(gen_random_uuid(),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','prescription','https://api.trial.ezyvet.com'));
select stage_ezyvet_import_page_core((select (v->>'id')::uuid from data where k='generic-prescription'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='generic-prescription'),1,true,'[{"external_id":"103","payload":{"id":103,"animal_id":77}}]');
set local role service_role;
select throws_ok($$select claim_ezyvet_prescriptionitem_import(gen_random_uuid(),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','prescriptionitem','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),(select id from ezyvet_import_snapshots where resource='prescription' and external_id='103'),(select payload_hash from ezyvet_import_snapshots where resource='prescription' and external_id='103'),1)$$,'40001','SOURCE_PRESCRIPTION_STALE','Generic-only prescription cannot provide scoped eligibility');
select throws_ok($$select claim_ezyvet_prescriptionitem_import(gen_random_uuid(),'db560000-0000-4000-8000-000000000001','different-site','prescriptionitem','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),(select (v->>'id')::uuid from data where k='prescription'),(select v->>'payload_hash' from data where k='prescription'),1)$$,'42501',null,'Mapping cannot cross sites');
reset role;
select is((select count(*)::integer from ezyvet_import_snapshots where resource='prescriptionitem' and external_id='501'),1,'Generic-first snapshot gains scoped receipt without duplicate bytes');
set local role anon;
select throws_ok($$select list_ezyvet_prescriptionitem_candidates(gen_random_uuid())$$,'42501',null,'Anonymous candidate access denied');
reset role;
select * from finish();rollback;
